function maxOverlap(intervals) {
  const events = [];
  for (const [s, e] of intervals) {
    events.push([s, 1]);
    events.push([e, -1]);
  }
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  let maxCount = 0, count = 0;
  for (const [_, delta] of events) {
    count += delta;
    maxCount = Math.max(maxCount, count);
  }
  return maxCount;
}

