function subsetSumExists(arr, T) {
  const n = arr.length;
  const mid = Math.floor(n / 2);
  const left = arr.slice(0, mid);
  const right = arr.slice(mid);
  const leftSums = getAllSums(left);
  const rightSums = getAllSums(right);
  rightSums.sort((a, b) => a - b);
  for (const s of leftSums) {
    const need = T - s;
    let lo = 0, hi = rightSums.length - 1;
    while (lo <= hi) {
      const m = (lo + hi) >> 1;
      if (rightSums[m] === need) return true;
      rightSums[m] < need ? lo = m + 1 : hi = m - 1;
    }
  }
  return false;
}
function getAllSums(arr) {
  const sums = [0];
  for (const x of arr)
    for (let i = sums.length - 1; i >= 0; i--)
      sums.push(sums[i] + x);
  return sums;
}

