bool subsetSumExists(vector<int>& arr, int T) {
    int n = arr.size(), mid = n / 2;
    auto leftSums = getAllSums(arr, 0, mid);
    auto rightSums = getAllSums(arr, mid, n);
    sort(rightSums.begin(), rightSums.end());
    for (int s : leftSums) {
        int need = T - s;
        if (binary_search(rightSums.begin(), rightSums.end(), need))
            return true;
    }
    return false;
}

