public boolean subsetSumExists(int[] arr, int T) {
    int mid = arr.length / 2;
    List<Integer> left = getAllSums(arr, 0, mid);
    List<Integer> right = getAllSums(arr, mid, arr.length);
    Collections.sort(right);
    for (int s : left) {
        int need = T - s;
        int idx = Collections.binarySearch(right, need);
        if (idx >= 0) return true;
    }
    return false;
}

