class LazySegTree {
  constructor(n) {
    this.n = n;
    this.tree = new Array(4 * n).fill(0);
    this.lazy = new Array(4 * n).fill(0);
  }
  build(arr, node, s, e) {
    if (s === e) { this.tree[node] = arr[s]; return; }
    const mid = (s + e) >> 1;
    this.build(arr, 2*node, s, mid);
    this.build(arr, 2*node+1, mid+1, e);
    this.tree[node] = this.tree[2*node] + this.tree[2*node+1];
  }
  pushDown(node, s, e) {
    if (this.lazy[node]) {
      const mid = (s + e) >> 1;
      this.tree[2*node] += this.lazy[node] * (mid - s + 1);
      this.tree[2*node+1] += this.lazy[node] * (e - mid);
      this.lazy[2*node] += this.lazy[node];
      this.lazy[2*node+1] += this.lazy[node];
      this.lazy[node] = 0;
    }
  }
  update(node, s, e, l, r, val) {
    if (r < s || e < l) return;
    if (l <= s && e <= r) {
      this.tree[node] += val * (e - s + 1);
      this.lazy[node] += val;
      return;
    }
    this.pushDown(node, s, e);
    const mid = (s + e) >> 1;
    this.update(2*node, s, mid, l, r, val);
    this.update(2*node+1, mid+1, e, l, r, val);
    this.tree[node] = this.tree[2*node] + this.tree[2*node+1];
  }
  query(node, s, e, l, r) {
    if (r < s || e < l) return 0;
    if (l <= s && e <= r) return this.tree[node];
    this.pushDown(node, s, e);
    const mid = (s + e) >> 1;
    return this.query(2*node, s, mid, l, r) + this.query(2*node+1, mid+1, e, l, r);
  }
}

