        int mid = (s+e)/2;
        tree[2*node] += lazy[node]*(mid-s+1);
        tree[2*node+1] += lazy[node]*(e-mid);
        lazy[2*node] += lazy[node];
        lazy[2*node+1] += lazy[node];
        lazy[node] = 0;
    }
    void update(int node,int s,int e,int l,int r,long val){
        if(r<s||e<l) return;
        if(l<=s&&e<=r){tree[node]+=val*(e-s+1);lazy[node]+=val;return;}
        pushDown(node,s,e);
        int mid=(s+e)/2;
        update(2*node,s,mid,l,r,val);
        update(2*node+1,mid+1,e,l,r,val);
        tree[node]=tree[2*node]+tree[2*node+1];
    }
    long query(int node,int s,int e,int l,int r){
        if(r<s||e<l) return 0;
        if(l<=s&&e<=r) return tree[node];
        pushDown(node,s,e);
        int mid=(s+e)/2;
        return query(2*node,s,mid,l,r)+query(2*node+1,mid+1,e,l,r);
    }
