def z_array(s):
    n = len(s)
    z = [0] * n
    z[0] = n
    l = r = 0
    for i in range(1, n):
        if i < r:
            z[i] = min(r - i, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l, r = i, i + z[i]
    return z

def find_pattern(text, pattern):
    s = pattern + '$' + text
    z = z_array(s)
    m = len(pattern)
    return [i - m - 1 for i in range(m+1, len(s)) if z[i] == m]

