function manacher(s) {
  const t = '#' + s.split('').join('#') + '#';
  const n = t.length, p = new Array(n).fill(0);
  let c = 0, r = 0;
  for (let i = 0; i < n; i++) {
    const mirror = 2 * c - i;
    if (i < r) p[i] = Math.min(r - i, p[mirror]);
    while (i + p[i] + 1 < n && i - p[i] - 1 >= 0 &&
           t[i + p[i] + 1] === t[i - p[i] - 1]) p[i]++;
    if (i + p[i] > r) { c = i; r = i + p[i]; }
  }
  const maxR = Math.max(...p);
  const centerIdx = p.indexOf(maxR);
  const start = (centerIdx - maxR) / 2;
  return s.substring(start, start + maxR);
}

