public String manacher(String s) {
    StringBuilder sb = new StringBuilder("#");
    for (char c : s.toCharArray()) { sb.append(c); sb.append('#'); }
    String t = sb.toString();
    int n = t.length();
    int[] p = new int[n];
    int c = 0, r = 0;
    for (int i = 0; i < n; i++) {
        int mirror = 2*c - i;
        if (i < r) p[i] = Math.min(r-i, p[mirror]);
        while (i+p[i]+1 < n && i-p[i]-1 >= 0 && t.charAt(i+p[i]+1) == t.charAt(i-p[i]-1)) p[i]++;
        if (i+p[i] > r) { c=i; r=i+p[i]; }
    }
    int maxR = 0, ci = 0;
    for (int i = 0; i < n; i++) if (p[i] > maxR) { maxR = p[i]; ci = i; }
    return s.substring((ci-maxR)/2, (ci-maxR)/2+maxR);
}

