function buildSA(s) {
  s += '$';
  const n = s.length;
  let sa = Array.from({length: n}, (_, i) => i);
  let rank = s.split('').map(c => c.charCodeAt(0));
  for (let gap = 1; gap < n; gap *= 2) {
    const rankCopy = [...rank];
    const key = i => [rankCopy[i], i + gap < n ? rankCopy[i + gap] : -1];
    sa.sort((a, b) => {
      const ka = key(a), kb = key(b);
      return ka[0] - kb[0] || ka[1] - kb[1];
    });
    rank[sa[0]] = 0;
    for (let i = 1; i < n; i++)
      rank[sa[i]] = rank[sa[i-1]] + (JSON.stringify(key(sa[i])) !== JSON.stringify(key(sa[i-1])) ? 1 : 0);
  }
  return sa;
}

