def build_sa(s):
    s += '$'
    n = len(s)
    sa = sorted(range(n), key=lambda i: s[i:])
    rank = [0] * n
    for i, idx in enumerate(sa):
        rank[idx] = i
    gap = 1
    while gap < n:
        def key(i):
            return (rank[i], rank[i+gap] if i+gap < n else -1)
        sa.sort(key=key)
        tmp = [0] * n
        tmp[sa[0]] = 0
        for i in range(1, n):
            tmp[sa[i]] = tmp[sa[i-1]] + (1 if key(sa[i]) != key(sa[i-1]) else 0)
        rank = tmp
        gap *= 2
    return sa

