public int[] buildSA(String s) {
    s += '$';
    int n = s.length();
    Integer[] sa = new Integer[n];
    for (int i=0;i<n;i++) sa[i]=i;
    int[] rank = new int[n];
    for (int i=0;i<n;i++) rank[i]=s.charAt(i);
    final int[] r = rank;
    for (int gap=1; gap<n; gap*=2) {
        final int g = gap;
        Arrays.sort(sa,(a,b)->{
            if(r[a]!=r[b]) return r[a]-r[b];
            int ra=a+g<n?r[a+g]:-1;
            int rb=b+g<n?r[b+g]:-1;
            return ra-rb;
        });
        int[] tmp=new int[n];
        tmp[sa[0]]=0;
        for(int i=1;i<n;i++){
            int a=sa[i-1],b=sa[i];
            boolean diff=r[a]!=r[b]||(a+g<n?r[a+g]:-1)!=(b+g<n?r[b+g]:-1);
            tmp[sa[i]]=tmp[sa[i-1]]+(diff?1:0);
        }
        System.arraycopy(tmp,0,r,0,n);
    }
    return Arrays.stream(sa).mapToInt(Integer::intValue).toArray();
}

