class OSTNode {
  constructor(val) {
    this.val = val; this.left = this.right = null; this.size = 1;
  }
}
function getSize(node) { return node ? node.size : 0; }
function insert(root, val) {
  if (!root) return new OSTNode(val);
  if (val < root.val) root.left = insert(root.left, val);
  else root.right = insert(root.right, val);
  root.size = 1 + getSize(root.left) + getSize(root.right);
  return root;
}
function select(root, k) {
  const leftSize = getSize(root.left);
  if (k <= leftSize) return select(root.left, k);
  if (k === leftSize + 1) return root.val;
  return select(root.right, k - leftSize - 1);
}
function rank(root, val) {
  if (!root) return 0;
  if (val < root.val) return rank(root.left, val);
  if (val > root.val) return 1 + getSize(root.left) + rank(root.right, val);
  return getSize(root.left) + 1;
}

