class OSTNode:
    def __init__(self, val):
        self.val = val
        self.left = self.right = None
        self.size = 1

def size(node):
    return node.size if node else 0

def insert(root, val):
    if not root: return OSTNode(val)
    if val < root.val: root.left = insert(root.left, val)
    else: root.right = insert(root.right, val)
    root.size = 1 + size(root.left) + size(root.right)
    return root

def select(root, k):
    ls = size(root.left)
    if k <= ls: return select(root.left, k)
    if k == ls + 1: return root.val
    return select(root.right, k - ls - 1)

def rank(root, val):
    if not root: return 0
    if val < root.val: return rank(root.left, val)
    if val > root.val: return 1 + size(root.left) + rank(root.right, val)
    return size(root.left) + 1

