  hash(item, seed) {
    let h = seed;
    for (const c of String(item)) h = (h * 31 + c.charCodeAt(0)) % this.m;
    return ((h % this.m) + this.m) % this.m;
  }
  add(item) {
    for (let i = 0; i < this.k; i++) {
      const pos = this.hash(item, i);
      this.bits[pos >> 3] |= (1 << (pos & 7));
    }
  }
  has(item) {
    for (let i = 0; i < this.k; i++) {
      const pos = this.hash(item, i);
      if (!(this.bits[pos >> 3] & (1 << (pos & 7)))) return false;
    }
    return true; // PROBABLY in set
  }
}

