class LSMTree {
  constructor() {
    this.memTable = new Map(); // In-memory buffer
    this.wal = [];             // Write-Ahead Log
    this.ssTables = [];        // Sorted String Tables (simplified as arrays)
    this.threshold = 4;        // Flush when memTable hits threshold
  }
  write(key, value) {
    this.wal.push({key, value}); // Durability
    this.memTable.set(key, value);
    if (this.memTable.size >= this.threshold) this.flush();
  }
  flush() {
    // Sort memTable and create new SSTable
    const sorted = [...this.memTable.entries()].sort((a,b) => a[0].localeCompare(b[0]));
    this.ssTables.unshift(sorted); // Newest first
    this.memTable.clear();
    if (this.ssTables.length >= 4) this.compact();
  }
  compact() {
    // Merge all SSTables (simplified 2-way merge)
    const merged = new Map();
    for (const ss of this.ssTables.reverse())
      for (const [k,v] of ss) merged.set(k,v);
    this.ssTables = [Array.from(merged.entries()).sort()];
  }
  read(key) {
    if (this.memTable.has(key)) return this.memTable.get(key);
    for (const ss of this.ssTables) {
      // Binary search each SSTable
      const found = ss.find(([k]) => k === key);
      if (found) return found[1];
    }
    return null;
  }
}

