import sortedcontainers
class LSMTree:
    def __init__(self, threshold=4):
        self.mem_table = {}  # In-memory buffer (use SortedDict in real impl)
        self.ss_tables = []  # List of sorted lists (newest first)
        self.threshold = threshold
    def write(self, key, value):
        self.mem_table[key] = value
        if len(self.mem_table) >= self.threshold:
            self.flush()
    def flush(self):
        sorted_pairs = sorted(self.mem_table.items())
        self.ss_tables.insert(0, sorted_pairs)  # Newest first
        self.mem_table.clear()
        if len(self.ss_tables) >= 4:
            self.compact()
    def compact(self):
        merged = {}
        for ss in reversed(self.ss_tables):
            for k, v in ss:
                merged[k] = v
        self.ss_tables = [sorted(merged.items())]
    def read(self, key):
        if key in self.mem_table:
            return self.mem_table[key]
        for ss in self.ss_tables:
            # Binary search
            lo, hi = 0, len(ss)-1
            while lo <= hi:
                mid = (lo+hi)//2
                if ss[mid][0] == key: return ss[mid][1]
                elif ss[mid][0] < key: lo = mid+1
                else: hi = mid-1
        return None

