class QuadTree {
  constructor(x, y, w, h, capacity = 4) {
    this.bounds = {x, y, w, h};
    this.capacity = capacity;
    this.points = [];
    this.divided = false;
  }
  contains(px, py) {
    const {x,y,w,h} = this.bounds;
    return px >= x && px < x+w && py >= y && py < y+h;
  }
  intersects(rx, ry, rw, rh) {
    const {x,y,w,h} = this.bounds;
    return !(rx > x+w || rx+rw < x || ry > y+h || ry+rh < y);
  }
  subdivide() {
    const {x,y,w,h} = this.bounds;
    this.NW = new QuadTree(x, y, w/2, h/2, this.capacity);
    this.NE = new QuadTree(x+w/2, y, w/2, h/2, this.capacity);
    this.SW = new QuadTree(x, y+h/2, w/2, h/2, this.capacity);
    this.SE = new QuadTree(x+w/2, y+h/2, w/2, h/2, this.capacity);
    this.divided = true;
  }
  insert(px, py) {
    if (!this.contains(px, py)) return false;
    if (this.points.length < this.capacity) { this.points.push([px,py]); return true; }
    if (!this.divided) this.subdivide();
    return this.NW.insert(px,py)||this.NE.insert(px,py)||
           this.SW.insert(px,py)||this.SE.insert(px,py);
  }
  query(rx, ry, rw, rh, found = []) {
    if (!this.intersects(rx, ry, rw, rh)) return found;
    for (const [px,py] of this.points)
      if (px >= rx && px < rx+rw && py >= ry && py < ry+rh) found.push([px,py]);
    if (this.divided) {
      this.NW.query(rx,ry,rw,rh,found); this.NE.query(rx,ry,rw,rh,found);
      this.SW.query(rx,ry,rw,rh,found); this.SE.query(rx,ry,rw,rh,found);
    }
    return found;
  }
}

