class QuadTree:
    def __init__(self, x, y, w, h, capacity=4):
        self.bounds = (x, y, w, h)
        self.capacity = capacity
        self.points = []
        self.divided = False
        self.children = []
    def contains(self, px, py):
        x,y,w,h = self.bounds
        return x<=px<x+w and y<=py<y+h
    def intersects(self, rx, ry, rw, rh):
        x,y,w,h = self.bounds
        return not (rx>x+w or rx+rw<x or ry>y+h or ry+rh<y)
    def subdivide(self):
        x,y,w,h = self.bounds
        self.children = [
            QuadTree(x,y,w/2,h/2,self.capacity),
            QuadTree(x+w/2,y,w/2,h/2,self.capacity),
            QuadTree(x,y+h/2,w/2,h/2,self.capacity),
            QuadTree(x+w/2,y+h/2,w/2,h/2,self.capacity)
        ]
        self.divided = True
    def insert(self, px, py):
        if not self.contains(px, py): return False
        if len(self.points) < self.capacity:
            self.points.append((px,py)); return True
        if not self.divided: self.subdivide()
        return any(c.insert(px,py) for c in self.children)
    def query(self, rx, ry, rw, rh, found=None):
        if found is None: found = []
        if not self.intersects(rx,ry,rw,rh): return found
        for px,py in self.points:
            if rx<=px<rx+rw and ry<=py<ry+rh: found.append((px,py))
        if self.divided:
            for c in self.children: c.query(rx,ry,rw,rh,found)
        return found

