class KDNode {
  constructor(point) { this.point = point; this.left = this.right = null; }
}
function buildKDTree(points, depth = 0) {
  if (!points.length) return null;
  const k = points[0].length;
  const axis = depth % k;
  points.sort((a, b) => a[axis] - b[axis]);
  const mid = Math.floor(points.length / 2);
  const node = new KDNode(points[mid]);
  node.left = buildKDTree(points.slice(0, mid), depth + 1);
  node.right = buildKDTree(points.slice(mid + 1), depth + 1);
  return node;
}
function dist(a, b) { return Math.sqrt(a.reduce((s,v,i) => s + (v-b[i])**2, 0)); }
function nearestNeighbor(root, target, depth = 0, best = {node: null, dist: Infinity}) {
  if (!root) return best;
  const d = dist(root.point, target);
  if (d < best.dist) best = {node: root, dist: d};
  const axis = depth % target.length;
  const diff = target[axis] - root.point[axis];
  const near = diff < 0 ? root.left : root.right;
  const far = diff < 0 ? root.right : root.left;
  best = nearestNeighbor(near, target, depth + 1, best);
  if (Math.abs(diff) < best.dist) best = nearestNeighbor(far, target, depth + 1, best);
  return best;
}

