// Complexity analysis examples with explanations
// O(n log n): nested but halving
function mergeSort(arr) {
  // Recursion depth: log n levels
  // Each level: O(n) total work across all merge calls
  // Total: O(n log n)
  if (arr.length <= 1) return arr;
  const mid = arr.length >> 1;
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));
  return merge(left, right); // O(n) merge
}
// O(n) single pass with O(1) space
function maxSubarray(arr) {
  // One loop: O(n) iterations, O(1) each → O(n)
  // Space: O(1) — just 2 variables
  let maxSoFar = arr[0], maxEndingHere = arr[0];
  for (let i = 1; i < arr.length; i++) {
    maxEndingHere = Math.max(arr[i], maxEndingHere + arr[i]);
    maxSoFar = Math.max(maxSoFar, maxEndingHere);
  }
  return maxSoFar;
}

