  // Compute pattern hash
  let patHash = 0, power = 1;
  for (let i = 0; i < m; i++) {
    patHash = (patHash + (pattern.charCodeAt(i) - 96) * power) % MOD;
    if (i < m - 1) power = (power * BASE) % MOD;
  }

  // Compute first window hash
  let windowHash = 0, p = 1;
  for (let i = 0; i < m; i++) {
    windowHash = (windowHash + (text.charCodeAt(i) - 96) * p) % MOD;
    if (i < m - 1) p = (p * BASE) % MOD;
  }

  const result = [];
  for (let i = 0; i <= n - m; i++) {
    if (windowHash === patHash && text.slice(i, i + m) === pattern) {
      result.push(i);
    }
    if (i < n - m) {
      windowHash = (windowHash - (text.charCodeAt(i) - 96) + MOD) % MOD;
      windowHash = (windowHash * BASE + (text.charCodeAt(i + m) - 96)) % MOD;
    }
  }
  return result;
}

