public List<Integer> rabinKarp(String text, String pattern) {
    final long BASE = 31, MOD = (long)1e9 + 7;
    int n = text.length(), m = pattern.length();
    if (m > n) return new ArrayList<>();
    long patHash = 0, winHash = 0, power = 1;
    for (int i = 0; i < m; i++) {
        patHash = (patHash + (pattern.charAt(i) - 'a' + 1) * power) % MOD;
        winHash = (winHash + (text.charAt(i) - 'a' + 1) * power) % MOD;
        if (i < m - 1) power = (power * BASE) % MOD;
    }
    List<Integer> res = new ArrayList<>();
    for (int i = 0; i <= n - m; i++) {
        if (winHash == patHash && text.substring(i, i+m).equals(pattern)) res.add(i);
        if (i < n - m) {
            winHash = (winHash - (text.charAt(i) - 'a' + 1) + MOD) % MOD;
            winHash = (winHash * BASE + (text.charAt(i+m) - 'a' + 1)) % MOD;
        }
    }
    return res;
}
